import java.util.*;
import java.io.*;

public class MazeFlow {
    static final int MAXN = 200;
    static final int MAXM = 100000;
    static final int INF = 100000000;

    static int[][] maze_grid = new int[20][20];
    static int[][] graph_adj = new int[MAXN][MAXN];
    static int n, total_nodes, t;
    static String line_input;
    static int[][] hu_list = new int[MAXN][3], re_list = new int[MAXN][3];
    static int zr, zc;
    static int cX, cY;
    static int[] move_dir_r = {0, 0, -1, 1};
    static int[] move_dir_c = {-1, 1, 0, 0};

    static int nodeIndex(int r, int c) {
        if (r > 0 && r <= n && c > 0 && c <= n && maze_grid[r][c] != -1)
            return (r - 1) * n + c;
        return -1;
    }

    static void setupGraph() {
        total_nodes = n * n;
        for (int[] row : graph_adj)
            Arrays.fill(row, -1);
        for (int r1 = 1; r1 <= n; r1++) {
            for (int c1 = 1; c1 <= n; c1++) {
                if (maze_grid[r1][c1] == -1) continue;
                int p1 = (r1 - 1) * n + c1;
                graph_adj[p1][p1] = 0;
                for (int i = 0; i < 4; i++) {
                    int r2 = r1 + move_dir_r[i];
                    int c2 = c1 + move_dir_c[i];
                    if (r2 > 0 && r2 <= n && c2 > 0 && c2 <= n && maze_grid[r2][c2] != -1) {
                        int p2 = (r2 - 1) * n + c2;
                        graph_adj[p1][p2] = 1;
                    }
                }
            }
        }
    }

    static int[] distArr = new int[MAXN];
    static int[] queueArr = new int[MAXM];

    static void computeDistances() {
        int front = 0, rear = 1;
        Arrays.fill(distArr, INF);
        int startNode = (zr - 1) * n + zc;
        distArr[startNode] = 0;
        queueArr[0] = startNode;
        while (front < rear) {
            int u = queueArr[front++];
            for (int v = 1; v <= total_nodes; v++) {
                if (graph_adj[u][v] == 1 && distArr[v] > distArr[u] + 1) {
                    distArr[v] = distArr[u] + 1;
                    queueArr[rear++] = v;
                }
            }
        }
    }

    static void computeAllPairs() {
        for (int k = 1; k <= total_nodes; k++) {
            for (int i = 1; i <= total_nodes; i++) {
                for (int j = 1; j <= total_nodes; j++) {
                    if (graph_adj[i][k] != -1 && graph_adj[k][j] != -1) {
                        if (graph_adj[i][j] == -1 || graph_adj[i][j] > graph_adj[i][k] + graph_adj[k][j]) {
                            graph_adj[i][j] = graph_adj[i][k] + graph_adj[k][j];
                        }
                    }
                }
            }
        }
    }

    static class EdgeFlow {
        int from, to, capacity, next;
        public EdgeFlow(int from, int to, int capacity, int next) {
            this.from = from;
            this.to = to;
            this.capacity = capacity;
            this.next = next;
        }
    }

    static ArrayList<EdgeFlow> flowEdges = new ArrayList<>();
    static int[] head = new int[MAXN];
    static int edgeCount;
    static int sNode, tNode;

    static void addFlowEdge(int u, int v, int cap) {
        flowEdges.add(new EdgeFlow(u, v, cap, head[u]));
        head[u] = flowEdges.size() - 1;
        flowEdges.add(new EdgeFlow(v, u, 0, head[v]));
        head[v] = flowEdges.size() - 1;
    }

    static int[] levelArr = new int[MAXN];

    static boolean buildLevel() {
        Arrays.fill(levelArr, -1);
        levelArr[sNode] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(sNode);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int i = head[u]; i != -1; i = flowEdges.get(i).next) {
                int v = flowEdges.get(i).to;
                if (flowEdges.get(i).capacity > 0 && levelArr[v] == -1) {
                    levelArr[v] = levelArr[u] + 1;
                    q.offer(v);
                }
            }
        }
        return levelArr[tNode] != -1;
    }

    static int[] ptrArr = new int[MAXN];

    static int sendFlow(int u, int flow) {
        if (u == tNode) return flow;
        for (int i = ptrArr[u]; i != -1; i = flowEdges.get(i).next) {
            int v = flowEdges.get(i).to;
            if (flowEdges.get(i).capacity > 0 && levelArr[v] == levelArr[u] + 1) {
                int pushed = sendFlow(v, Math.min(flow, flowEdges.get(i).capacity));
                if (pushed > 0) {
                    flowEdges.get(i).capacity -= pushed;
                    flowEdges.get(i ^ 1).capacity += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    static int computeMaxFlow() {
        int totalFlow = 0;
        while (buildLevel()) {
            Arrays.fill(ptrArr, 0);
            for (int i = 0; i <= total_nodes + 1; i++) {
                ptrArr[i] = head[i];
            }
            int pushed;
            while ((pushed = sendFlow(sNode, INF)) > 0) {
                totalFlow += pushed;
            }
        }
        return totalFlow;
    }

    static int solve() {
        maze_grid[zr][zc] = 0;
        setupGraph();
        computeDistances();
        maze_grid[zr][zc] = -1;
        setupGraph();
        computeAllPairs();
        flowEdges.clear();
        Arrays.fill(head, -1);
        edgeCount = 0;
        sNode = 0;
        tNode = cX + cY + 1;
        for (int i = 1; i <= cX; i++) {
            addFlowEdge(sNode, i, hu_list[i][2]);
        }
        for (int i = 1; i <= cY; i++) {
            addFlowEdge(cX + i, tNode, re_list[i][2]);
        }
        int p = (zr - 1) * n + zc;
        for (int i = 1; i <= cX; i++) {
            for (int j = 1; j <= cY; j++) {
                int p1 = (hu_list[i][0] - 1) * n + hu_list[i][1];
                int p2 = (re_list[j][0] - 1) * n + re_list[j][1];
                if (graph_adj[p1][p2] != -1 && graph_adj[p1][p2] <= t && graph_adj[p1][p2] < distArr[p2]) {
                    addFlowEdge(i, cX + j, INF);
                } else if (graph_adj[p1][p2] != -1 && graph_adj[p1][p2] <= t && graph_adj[p1][p2] == distArr[p2]) {
                    for (int z = 0; z < 4; z++) {
                        int rr = re_list[j][0] + move_dir_r[z];
                        int cc = re_list[j][1] + move_dir_c[z];
                        int pp = nodeIndex(rr, cc);
                        if (pp != -1) {
                            if (graph_adj[p1][pp] == graph_adj[p1][p2] - 1 && graph_adj[p1][pp] < distArr[pp]) {
                                addFlowEdge(i, cX + j, INF);
                            }
                        }
                    }
                }
            }
        }
        return computeMaxFlow();
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());
        cX = 0;
        cY = 0;
        for (int[] row : maze_grid)
            Arrays.fill(row, 0);
        for (int i = 1; i <= n; i++) {
            line_input = br.readLine();
            for (int j = 0; j < n; j++) {
                char ch = line_input.charAt(j);
                if (ch == 'Y') maze_grid[i][j + 1] = -1;
                else if (ch == 'Z') {
                    zr = i;
                    zc = j + 1;
                    maze_grid[i][j + 1] = -1;
                } else if (ch > '0' && ch <= '9') {
                    cX++;
                    hu_list[cX][0] = i;
                    hu_list[cX][1] = j + 1;
                    hu_list[cX][2] = ch - '0';
                }
            }
        }
        for (int i = 1; i <= n; i++) {
            line_input = br.readLine();
            for (int j = 0; j < n; j++) {
                char ch = line_input.charAt(j);
                if (ch > '0' && ch <= '9') {
                    cY++;
                    re_list[cY][0] = i;
                    re_list[cY][1] = j + 1;
                    re_list[cY][2] = ch - '0';
                }
            }
        }
        System.out.println(solve());
    }
}
